[CmdletBinding()]
param([string]$HayesPath = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference = "Stop"
$root=(Resolve-Path $HayesPath).Path
$allow=@('.gitignore','registry/test_quality_rules.json','registry/wave2d_evaluator_registry_v1_9.json','registry/wave2d_evaluator_registry_v1_9_publication_spec.json','src/hayes_verify/evaluator_families/test_quality.py','tests/test_test_quality_v19.py','scripts/Run-Wave2DImmutableBatch.ps1','scripts/build_test_quality_batch_registry.py','scripts/build_test_quality_v19_artifacts.py','scripts/build_test_quality_v19_authority_preflight.py','scripts/validate_test_quality_v19_prebatch.py','scripts/promote_test_quality_v19_batch.py','scripts/build_wave2d_v19_publication_artifacts.py','scripts/Test-Wave2DEvaluatorRegistryV19PublicationPreflight.ps1','scripts/Stage-Wave2DEvaluatorRegistryV19ForPublish.ps1','scripts/Publish-Wave2DEvaluatorRegistryV19.ps1','generated/wave2d/evaluator-expansion/test_quality_v19_authority_preflight.json','generated/wave2d/evaluator-expansion/TEST_QUALITY_V19_AUTHORITY_PREFLIGHT.md','generated/wave2d/evaluator-expansion/test_quality_v19_implementation_matrix.json','generated/wave2d/evaluator-expansion/test_quality_v19_family_coverage.json','generated/wave2d/evaluator-expansion/test_quality_v19_prebatch_validation.json','generated/wave2d/evaluator-expansion/test-quality-v19-verification/verification_manifest.json','generated/wave2d/evaluator-expansion/test_quality_registry_v1_9_certification.json','generated/wave2d/evaluator-expansion/wave2d_v1_9_publication_manifest.json','generated/wave2d/evaluator-expansion/post_v19_remaining_controls.json','generated/wave2d/evaluator-expansion/POST_V19_REMAINING_ASSESSMENT.md')
Push-Location $root
try { foreach($path in ($allow | Where-Object { $_ -notlike 'generated/*' })){ git add -- $path }; foreach($path in ($allow | Where-Object { $_ -like 'generated/*' })){ git add -f -- $path }; git diff --cached --name-status } finally { Pop-Location }